<?php
require_once __DIR__.'/config/config.php';require_login();$uid=(int)$_SESSION['user_id'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$code=strtoupper(trim($_POST['animal_code']??''));$name=trim($_POST['name']??'');$species=trim($_POST['species']??'Cattle');$breed=trim($_POST['breed']??'');$sex=$_POST['sex']??'Unknown';$dob=$_POST['date_of_birth']?:null;$colour=trim($_POST['colour_markings']??'');$ear=trim($_POST['ear_tag']??'');$notes=trim($_POST['notes']??'');if($code==='')$errors[]='Animal ID is required.';if(!in_array($sex,['Female','Male','Unknown'],true))$errors[]='Choose a valid sex.';if($species==='')$errors[]='Species is required.';if(!$errors){try{$stmt=$conn->prepare('INSERT INTO animals(animal_code,owner_id,name,species,breed,sex,date_of_birth,colour_markings,ear_tag,notes) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->bind_param('sissssssss',$code,$uid,$name,$species,$breed,$sex,$dob,$colour,$ear,$notes);$stmt->execute();flash('Livestock registered successfully.');header('Location: animals.php');exit;}catch(mysqli_sql_exception $e){$errors[]=$e->getCode()===1062?'That animal ID is already in use. Choose a unique ID.':'Could not save the animal. Check the details and try again.';}}}
$page_title='Register livestock';require __DIR__.'/includes/header.php';
?>
<?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><div class="form-card"><div class="panel-heading"><div><h3>Livestock profile</h3><p>Enter the details you currently know. Unknown details can be left blank.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field"><label>Livestock ID *</label><input name="animal_code" required maxlength="40" value="<?=e($_POST['animal_code']??'')?>" placeholder="e.g. HSZ-0001"><span class="hint">Use a unique ID from your own records.</span></div><div class="field"><label>Name (optional)</label><input name="name" maxlength="80" value="<?=e($_POST['name']??'')?>"></div><div class="field"><label>Species *</label><select name="species" required><option>Cattle</option><option>Goat</option><option>Sheep</option><option>Other</option></select></div><div class="field"><label>Breed</label><input name="breed" maxlength="80" value="<?=e($_POST['breed']??'')?>" placeholder="e.g. Mashona"></div><div class="field"><label>Sex</label><select name="sex"><option>Unknown</option><option>Female</option><option>Male</option></select></div><div class="field"><label>Date of birth (if known)</label><input type="date" name="date_of_birth" max="<?=date('Y-m-d')?>" value="<?=e($_POST['date_of_birth']??'')?>"></div><div class="field"><label>Colour / markings</label><input name="colour_markings" maxlength="120" value="<?=e($_POST['colour_markings']??'')?>"></div><div class="field"><label>Existing ear-tag number</label><input name="ear_tag" maxlength="80" value="<?=e($_POST['ear_tag']??'')?>"></div><div class="field full"><label>Notes</label><textarea name="notes" placeholder="Optional identifying notes"><?=e($_POST['notes']??'')?></textarea></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">Save livestock</button><a class="btn btn-light" href="animals.php">Cancel</a></div></form></div>
